Of course, you can then add this at the end and your message will even go away on its own \|\|\^
Code:
//-----------------------------------------------------------------------------
//  MessagesWithoutWaitingMZ for RPG Maker MZ by hatesec
//-----------------------------------------------------------------------------
//  For: RPGMAKER MZ
//  MessagesWithoutWaitingMZ.js
//-----------------------------------------------------------------------------
// Credit Hatesec, Lebal Drocer, Inc.
// https://lebal-drocer.com
//-----------------------------------------------------------------------------

/*:
 * @plugindesc (v.1.0) Allows the player to walk around during any show text event by typing \MOV in the show text message window.
 * @help Use the escape code \MOV in the message window to allow player movement during the display of that message.
 */

(function() {

    const _Window_Message_startMessage = Window_Message.prototype.startMessage;
    Window_Message.prototype.startMessage = function() {
        this._allowPlayerMovement = false;
        const texts = $gameMessage._texts.map(text => {
            if (text.includes("\\MOV")) {
                this._allowPlayerMovement = true;
                return text.replace("\\MOV", "");
            }
            return text;
        });
        $gameMessage._texts = texts;
        _Window_Message_startMessage.call(this);
    };

    const _Window_Message_updateMessage = Window_Message.prototype.updateMessage;
    Window_Message.prototype.updateMessage = function() {
        if (this._allowPlayerMovement) {
            this._showFast = true;
            this._lineShowFast = true;
        }
        return _Window_Message_updateMessage.call(this);
    };

    const _Game_Player_canMove = Game_Player.prototype.canMove;
    Game_Player.prototype.canMove = function() {
        if ($gameMessage.isBusy() && SceneManager._scene._messageWindow._allowPlayerMovement) {
            return true;
        }
        return _Game_Player_canMove.call(this);
    };

})();

